export function mountAccountDeletion(cloud){
 const dialog=document.createElement('dialog');dialog.className='social-dialog delete-account-dialog';dialog.setAttribute('aria-labelledby','deleteAccountTitle');dialog.innerHTML='<div class="dialog-heading"><h2 id="deleteAccountTitle">Delete your ProSolver account?</h2><button id="cancelAccountDeletion" aria-label="Close account deletion">×</button></div><p>Your profile, progress, notes, drafts, photo, follows, chat messages and submitted solutions will be permanently removed. Unpublished problems you created will be deleted. Published problems stay in the community library without your account attribution.</p><p>Your Google account is kept. Confirm your identity with Google before removal.</p><label class="delete-confirm-label">Type DELETE to confirm<input id="deleteAccountConfirmation" autocomplete="off" spellcheck="false" placeholder="DELETE"></label><p id="deleteAccountStatus" role="status"></p><div class="delete-actions"><button id="cancelDeletion" class="button secondary">Cancel</button><button id="confirmAccountDeletion" class="danger-button" disabled>Verify and delete account</button></div>';document.body.append(dialog);
 const $=id=>document.getElementById(id),confirm=$('confirmAccountDeletion'),field=$('deleteAccountConfirmation');let busy=false;
 const menuButton=document.createElement('button');menuButton.type='button';menuButton.hidden=!cloud.user;menuButton.className='delete-menu-button';menuButton.textContent='Delete account';$('menuAccountSlot')?.append(menuButton);
 function open(){field.value='';confirm.disabled=true;$('deleteAccountStatus').textContent=cloud.user?'':'Sign in to manage your account.';confirm.textContent=cloud.deletionPending?'Retry deletion':'Verify and delete account';if(!dialog.open)dialog.showModal();}
 menuButton.onclick=open;if($('deleteAccountButton'))$('deleteAccountButton').onclick=open;
 field.oninput=()=>{confirm.disabled=busy||!cloud.user||field.value!=='DELETE';};const close=()=>{if(!busy)dialog.close();};$('cancelAccountDeletion').onclick=close;$('cancelDeletion').onclick=close;dialog.addEventListener('cancel',e=>{if(busy)e.preventDefault();});
 confirm.onclick=async()=>{if(field.value!=='DELETE'||busy||!cloud.user)return;busy=true;confirm.disabled=true;$('deleteAccountStatus').textContent=cloud.deletionPending?'Finishing account removal…':'Verify your Google identity to continue…';try{await cloud.deleteAccount();dialog.close();location.replace('./index.html?account=deleted#map');}catch(e){$('deleteAccountStatus').textContent=e.message;confirm.textContent=cloud.deletionPending?'Retry deletion':'Verify and delete account';}finally{busy=false;confirm.disabled=field.value!=='DELETE';}};
 return{open};
}
